sql.if:
AND (
mp.tenant_id = #{tenantId}
OR (
(mp.tenant_id IS NULL OR mp.tenant_id = '')
AND (
(
(mp.linked_app_id IS NOT NULL AND mp.linked_app_id <> '')
AND (
linked.tenant_id = #{tenantId}

  OR ((linked.tenant_id IS NULL OR linked.tenant_id = '') AND linked.union_id IN

    #{scopeUnionId}

  )

)
)
OR
(
(mp.linked_app_id IS NULL OR mp.linked_app_id = '')
AND (
creator.tenant_id = #{tenantId}

  OR ((creator.tenant_id IS NULL OR creator.tenant_id = '') AND mp.creator_id IN

    #{scopeUnionId}

  )

)
)
)
)
)

AND (
(
(mp.linked_app_id IS NOT NULL AND mp.linked_app_id <> '')
AND (

  linked_owner.dept_id IN

    #{scopeDeptId}



  OR


  linked.union_id IN

    #{scopeUnionId}


)
)
OR
(
(mp.linked_app_id IS NULL OR mp.linked_app_id = '')
AND (

  creator.dept_id IN

    #{scopeDeptId}



  OR


  mp.creator_id IN

    #{scopeUnionId}


)
)
)

mapper.select:


  mp.deleted = 0

    AND mp.name LIKE CONCAT('%', #{name}, '%')


    AND mp.status = #{status}


    AND mp.creator_id = #{creatorId}



ORDER BY mp.create_time DESC
